export function parseAgenda(text) {
  const value=JSON.parse(text);
  if (!value || typeof value.title!=='string' || !Array.isArray(value.days) || !value.days.length) throw new Error('An event needs a title and at least one day.');
  const ids=new Set();
  for (const day of value.days) {
    if (typeof day.name!=='string' || !Array.isArray(day.sessions)) throw new Error('Each day needs a name and sessions.');
    for (const session of day.sessions) {
      if (!['id','title','location','description'].every(key=>typeof session[key]==='string') || ids.has(session.id)) throw new Error('Each session needs a unique id, title, location and description.');
      ids.add(session.id);
    }
  }
  return value;
}
export function noteKey(session) { return 'agenda-note:'+session.id; }

