if (localStorage.getItem('conference-agenda') === null) {
  const saved = await (await fetch('../examples/saved-visit.json')).json();
  for (const [key, value] of Object.entries(saved)) {
    if (localStorage.getItem(key) === null) localStorage.setItem(key, value);
  }
}
import { parseAgenda, noteKey } from './model.mjs';
const initial=await (await fetch('default.json')).text();
let agenda;
try { agenda=parseAgenda(localStorage.getItem('conference-agenda')||initial); } catch { agenda=parseAgenda(initial); }
let selected=0;
const days=document.querySelector('#days');
const sessions=document.querySelector('#sessions');
function renderSessions() {
  sessions.replaceChildren();
  for (const session of agenda.days[selected].sessions) {
    const card=document.createElement('article'); card.className='session';
    const heading=document.createElement('h3'); heading.textContent=session.title;
    const details=document.createElement('details');
    const summary=document.createElement('summary'); summary.textContent='Session details';
    const location=document.createElement('p'); location.className='location'; location.textContent=session.location;
    const description=document.createElement('div'); description.className='description'; description.textContent=session.description;
    details.append(summary,location,description);
    const label=document.createElement('label'); label.textContent='Your notes';
    const input=document.createElement('textarea'); input.setAttribute('aria-label','Your notes for '+session.title); input.rows=3; input.value=localStorage.getItem(noteKey(session))||'';
    input.oninput=()=>localStorage.setItem(noteKey(session),input.value);
    label.append(input); card.append(heading,details,label); sessions.append(card);
  }
}
function choose(index) {
  selected=index;
  [...days.children].forEach((button,i)=>{button.setAttribute('aria-selected',String(i===selected));button.tabIndex=i===selected?0:-1;});
  renderSessions();
}
function render() {
  document.querySelector('#event-title').textContent=agenda.title; days.replaceChildren();
  agenda.days.forEach((day,index)=>{
    const button=document.createElement('button'); button.setAttribute('role','tab'); button.textContent=day.name; button.setAttribute('aria-selected',String(index===selected));button.tabIndex=index===selected?0:-1;
    button.onclick=()=>choose(index);
    button.onkeydown=event=>{
      const next=event.key==='ArrowRight'?(index+1)%agenda.days.length:event.key==='ArrowLeft'?(index+agenda.days.length-1)%agenda.days.length:event.key==='Home'?0:event.key==='End'?agenda.days.length-1:null;
      if(next!==null){event.preventDefault();choose(next);days.children[next].focus({preventScroll:true});}
    };
    days.append(button);
  });
  renderSessions();
}
document.querySelector('#load').onclick=()=>{
  const error=document.querySelector('#load-error');
  try { const next=parseAgenda(document.querySelector('#agenda-input').value); agenda=next;selected=0;localStorage.setItem('conference-agenda',JSON.stringify(agenda));error.textContent='';render(); }
  catch(problem) { error.textContent=problem.message; }
};
render();

files.checks/agenda.mjs:
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { parseAgenda,noteKey } from '../app/model.mjs';
const simple=parseAgenda(await readFile(new URL('../app/default.json',import.meta.url),'utf8'));
const event=parseAgenda(await readFile(new URL('../examples/river-conference.json',import.meta.url),'utf8'));
assert.equal(simple.days.length,2);
assert.equal(event.days.length,8);
assert.ok(event.days[0].sessions[0].description.includes('\n\n'));
assert.notEqual(noteKey(event.days[0].sessions[0]),noteKey(event.days[1].sessions[0]));
assert.throws(()=>parseAgenda('{'));
assert.throws(()=>parseAgenda('{"title":"Invalid","days":[]}'));
console.log('Agenda data and note keys passed.');

